Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// To update deliveryshipetoGLN field 
    /// </summary>
    /// <param name="sender">Form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(InventLocation, InventLocation), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventLocation_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        InventLocation      InventLocation = sender.cursor();

        if(InventLocation.METUseDevAddressforShiptoGLNSetting)
        {
            sender.object(fieldNum(InventLocation, METPODeliveryShiptoGLN)).enabled(NoYes::No);
            InventLocation.METPODeliveryShiptoGLN = METConstants::emptyString;
        }
        else
        {
            sender.object(fieldNum(InventLocation, METPODeliveryShiptoGLN)).enabled(NoYes::Yes);
        }
    }
